import { useProgressiveRows } from '@/hooks/useProgressiveRows';
import { useMemo, useState, type ReactNode } from 'react';
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react';
import type { Player, Position } from '@/types/player';
import { cn } from '@/lib/utils';
import type { Overall } from '@/config/skillGrades';
import PositionBadge from '../PositionBadge';
import AwardsCell from '../AwardsCell';
import PlayerCardLayer from '../player/PlayerCardLayer';
import { useNewSlot } from '@/utils/slot';
import { warmPlayerCard } from '../player/warmPlayerCard';
import TeamBadge from '../brand/TeamBadge';
import TeamLogo, { resolveTeam } from '../brand/TeamLogo';
import { calculateLeaders } from '@/utils/csvParser';
import { playerKey } from '@/config/ovr';
import { IS_NFL } from '@/config/edition';
import { useGamePool } from '@/utils/useOfficialOvr';
import { useSkillRatings } from '@/utils/useSkillRatings';
import { getTeamColors } from '@/utils/teamColors';
import { HeaderTip, LeaderStat, PlayerNameCell, TierMetric } from './cells';
import { peekProps } from '@/components/peek/peekProps';
import { displayName } from '@/utils/displayName';
import { CAREER_LABEL } from '@/config/ovr';

export interface StatColumn<T> {
  key: string;
  label: string;
  tip?: string;
  get: (p: T) => number;
  /** Highlight the leader in this column */
  leader?: boolean;
  decimals?: number;
}

export interface MetricColumn {
  key: 'trueTalent' | 'dominance' | 'careerLegacy' | 'tpg';
  label: string;
  tip: string;
  format: 'number' | 'decimal';
  /** Part of the default "Key" column set (the rest show with "All columns") */
  essential?: boolean;
}

export const METRIC_COLUMNS: MetricColumn[] = [
  { key: 'trueTalent', label: 'Talent', tip: 'True Talent: production-based rating for the career', format: 'number' },
  { key: 'dominance', label: 'Dom', tip: 'Dominance: talent plus award points (rings, MVPs, POY, SB MVP)', format: 'number' },
  { key: 'careerLegacy', label: 'Legacy', tip: 'Career Legacy: talent, dominance and longevity combined', format: 'number', essential: true },
  { key: 'tpg', label: 'TPG', tip: 'Talent per game, adjusted for career length', format: 'decimal' },
];

interface PlayerStatTableProps<T extends Player> {
  title: string;
  position: Position;
  players: T[];
  columns: StatColumn<T>[];
  searchQuery?: string;
  isDefense?: boolean;
  /** Resolve the team to display (e.g. apply local overrides) */
  getTeam?: (p: T) => string | undefined;
  headerActions?: ReactNode;
  children?: ReactNode;
}

const RATING_KEYS = new Set(['szn', 'car', 'skill']);

/** Skill rating with its letter grade chip. */
const SkillCell = ({ overall }: { overall?: Overall }) =>
  overall ? (
    <span className="inline-flex items-center justify-end gap-1.5" title={`Career skill ${overall.grade.grade} · ${Math.round(overall.pct)}th percentile at the position (same as the Deep Dive's Career view)`}>
      <span className="rounded px-1 font-display text-xs font-extrabold text-[#0b1020]" style={{ background: overall.grade.color }}>
        {overall.grade.grade}
      </span>
      <span className="font-display text-base font-bold tabular-nums">{overall.rating}</span>
    </span>
  ) : (
    <span className="text-muted-foreground">—</span>
  );

type SortState = { key: string; dir: 'asc' | 'desc' } | null;

const SortHeader = ({
  k,
  label,
  tip,
  className,
  sort,
  onToggle,
}: {
  k: string;
  label: string;
  tip?: string;
  className?: string;
  sort: SortState;
  onToggle: (key: string) => void;
}) => {
  const active = sort?.key === k;
  const Icon = !active ? ArrowUpDown : sort!.dir === 'desc' ? ArrowDown : ArrowUp;
  return (
    <th
      scope="col"
      className={cn('num', className)}
      aria-sort={active ? (sort!.dir === 'desc' ? 'descending' : 'ascending') : 'none'}
    >
      <HeaderTip label={label} tip={tip}>
        <button
          type="button"
          onClick={() => onToggle(k)}
          className={cn('tap-40 inline-flex items-center gap-1 uppercase tracking-wider hover:text-foreground', active && 'text-gold')}
        >
          {label}
          <Icon className={cn('h-3 w-3', !active && 'opacity-40')} aria-hidden="true" />
        </button>
      </HeaderTip>
    </th>
  );
};

function PlayerStatTable<T extends Player>({
  title,
  position,
  players,
  columns,
  searchQuery = '',
  isDefense = false,
  getTeam = (p) => p.team,
  headerActions,
  children,
}: PlayerStatTableProps<T>) {
  // The open player card lives in a slot: opening it re-renders the card only, not every row of the table
  const cardSlot = useNewSlot<Player | null>(null);
  const setSelectedPlayer = cardSlot.set;
  const [sort, setSort] = useState<SortState>(null);
  // Key columns by default (career line, Legacy, OVR, Skill); "All columns" adds awards, Talent, Dom and TPG
  const [allCols, setAllCols] = useState(false);
  const metricCols = allCols ? METRIC_COLUMNS : METRIC_COLUMNS.filter((m) => m.essential);
  const { careerOvrMap, seasonOvr } = useGamePool();
  // SZN = this season's OVR (active players who played it); CAR = the career OVR (everyone)
  const sznOf = (p: Player) => (p.status === 'Active' ? seasonOvr?.ovr[playerKey(p)] : undefined);
  const skillMap = useSkillRatings();
  const ratingOf = (key: string, p: Player) =>
    key === 'car' ? careerOvrMap.get(playerKey(p)) : key === 'szn' ? sznOf(p) : key === 'skill' ? skillMap.get(playerKey(p))?.rating : undefined;

  const filteredPlayers = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return players.filter((p) => {
      const matchesSearch = !q || p.name.toLowerCase().includes(q) || (p.nickname ?? '').toLowerCase().includes(q);
      return matchesSearch;
    });
  }, [players, searchQuery]);

  const leaders = useMemo(
    () =>
      calculateLeaders(filteredPlayers, [
        ...columns.filter((c) => c.leader !== false).map((c) => c.key),
        ...METRIC_COLUMNS.map((m) => m.key),
      ]),
    [filteredPlayers, columns],
  );
  const isLeader = (name: string, key: string) => leaders.get(key)?.name === name;

  const sortedPlayers = useMemo(() => {
    if (!sort) return filteredPlayers;
    const getter =
      columns.find((c) => c.key === sort.key)?.get ??
      (RATING_KEYS.has(sort.key)
        ? (p: T) => ratingOf(sort.key, p) ?? -1
        : (p: T) => Number((p as unknown as Record<string, unknown>)[sort.key]) || 0);
    const dir = sort.dir === 'desc' ? -1 : 1;
    return [...filteredPlayers].sort((a, b) => dir * ((getter(a) || 0) - (getter(b) || 0)));
    // ratingOf reads the two rating maps
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filteredPlayers, sort, columns, careerOvrMap, seasonOvr, skillMap]);

  // Rows mount in slices as the table is read (hooks/useProgressiveRows); a new sort, filter or search starts over
  const rowWindow = useProgressiveRows(sortedPlayers.length, { resetKey: `${sort?.key}|${sort?.dir}|${searchQuery}|${filteredPlayers.length}` });

  if (filteredPlayers.length === 0) return null;

  const toggleSort = (key: string) =>
    setSort((s) => (!s || s.key !== key ? { key, dir: 'desc' } : s.dir === 'desc' ? { key, dir: 'asc' } : null));

  return (
    <>
      <section className="glass-card overflow-hidden animate-slide-in" aria-label={title}>
        <div className="flex flex-wrap items-center gap-3 px-4 py-3 border-b border-border">
          <PositionBadge position={position} />
          <h3 className="font-display text-xl font-bold uppercase tracking-wide">{title}</h3>
          <span className="font-pixel text-[10px] text-muted-foreground">{filteredPlayers.length} PLAYERS</span>
          <div className="ml-auto flex items-center gap-2">
            {headerActions}
            <div role="group" aria-label="Columns" className="flex gap-1 rounded-lg bg-secondary/50 p-1">
              {[
                { on: false, label: 'Key' },
                { on: true, label: 'All columns' },
              ].map((o) => (
                <button
                  key={o.label}
                  type="button"
                  aria-pressed={allCols === o.on}
                  onClick={() => setAllCols(o.on)}
                  className={cn(
                    'tap-40 rounded-md px-2.5 py-1 font-display text-xs font-bold uppercase tracking-wide transition-colors',
                    allCols === o.on ? 'bg-gold text-primary-foreground' : 'text-muted-foreground hover:text-foreground',
                  )}
                >
                  {o.label}
                </button>
              ))}
            </div>
          </div>
        </div>
        <div className="relative overflow-x-auto overscroll-x-contain">
          <table className="stats-table text-[13px]">
            <caption className="sr-only">
              {title} career statistics. Select a column header to sort, or a player name for details.
            </caption>
            <thead>
              <tr>
                <th scope="col" className="sticky-col">Player</th>
                <th scope="col">Team</th>
                {columns.map((c) => (
                  <SortHeader key={c.key} k={c.key} label={c.label} tip={c.tip} sort={sort} onToggle={toggleSort} />
                ))}
                {allCols && <th scope="col">Awards</th>}
                {metricCols.map((m) => (
                  <SortHeader key={m.key} k={m.key} label={m.label} tip={m.tip} sort={sort} onToggle={toggleSort} />
                ))}
                <SortHeader k="szn" label="SZN" tip="Season OVR (62–99): this season's line, ranked within the position among players who played it. Active players only" sort={sort} onToggle={toggleSort} />
                <SortHeader k="car" label={CAREER_LABEL} tip={IS_NFL ? "OVR, the career rating (62–99): 50% efficiency (era-adjusted, shrunk by sample) + 50% production and honours, ranked among qualified starters" : "Career OVR (62–99): career production and awards, ranked within the position (active and retired)"} sort={sort} onToggle={toggleSort} />
                <SortHeader k="skill" label="Skill" tip="Career skill rating: per-game skills and advanced factors graded against the position (S to F), ignores career length and awards. The Deep Dive's Career view shows the same grade; its This season view grades one season alone." sort={sort} onToggle={toggleSort} />
              </tr>
            </thead>
            <tbody>
              {sortedPlayers.slice(0, rowWindow.shown).map((player) => {
                const team = getTeam(player);
                const colors = getTeamColors(team);
                return (
                  <tr
                    key={`${displayName(player.name)}-${player.position}`}
                    className="cursor-pointer"
                    {...peekProps(player)}
                    onPointerDown={() => warmPlayerCard({ ...player, team })}
                    onClick={() => setSelectedPlayer({ ...player, team } as Player)}
                  >
                    <td
                      className="sticky-col max-w-[9.5rem] sm:max-w-[13rem]"
                      style={colors ? { boxShadow: `inset 3px 0 0 hsl(${colors.primary}), 1px 0 0 hsl(var(--border))` } : undefined}
                    >
                      <PlayerNameCell compact player={player} onSelect={() => setSelectedPlayer({ ...player, team } as Player)} />
                    </td>
                    {/* One team cue (the logo, beside the row's colour bar); the club's name is its alt text and tooltip */}
                    <td>
                      {resolveTeam(team) ? (
                        <span className="inline-flex" title={resolveTeam(team)!.fullName}>
                          <TeamLogo team={team} size={22} backed />
                        </span>
                      ) : (
                        <TeamBadge team={team} size="sm" />
                      )}
                    </td>
                    {columns.map((c) => (
                      <td key={c.key} className="num">
                        <LeaderStat
                          value={c.get(player)}
                          decimals={c.decimals}
                          isLeader={c.leader !== false && isLeader(player.name, c.key)}
                        />
                      </td>
                    ))}
                    {allCols && <td>
                      <AwardsCell
                        rings={player.rings}
                        mvp={player.mvp}
                        opoy={player.opoy}
                        sbmvp={player.sbmvp}
                        roty={player.roty}
                        isDefense={isDefense}
                        className="flex-nowrap gap-0.5"
                      />
                    </td>}
                    {metricCols.map((m) => (
                      <td key={m.key} className="num">
                        <TierMetric
                          value={player[m.key]}
                          metric={m.key}
                          format={m.format}
                          showLabel={false}
                          isLeader={isLeader(player.name, m.key)}
                        />
                      </td>
                    ))}
                    <td className="num font-display text-base font-bold tabular-nums">{sznOf(player) ?? '—'}</td>
                    <td className="num font-display text-base font-bold tabular-nums">{careerOvrMap.get(playerKey(player)) ?? '—'}</td>
                    <td className="num">
                      <SkillCell overall={skillMap.get(playerKey(player))} />
                    </td>
                  </tr>
                );
              })}
              {rowWindow.more > 0 && (
                <tr ref={rowWindow.sentinelRef}>
                  <td colSpan={99} className="py-3 text-center">
                    <button type="button" onClick={rowWindow.showMore} className="tap-40 text-xs font-semibold uppercase tracking-wider text-gold hover:underline">
                      Show more ({rowWindow.more.toLocaleString()} left)
                    </button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>

      {children}

      <PlayerCardLayer slot={cardSlot} />
    </>
  );
}

export default PlayerStatTable;
