import DeferredSection from '@/components/ui/DeferredSection';
import { Reveal, useAutoReveal } from '@/components/motion/Reveal';
import { Suspense, useEffect, useMemo, useRef, useState } from 'react';
import PixelLoader from '@/components/ui/PixelLoader';
import { useLeague } from '@/context/LeagueContext';
import type { Player } from '@/types/player';
import PlayerCardLayer from '../player/PlayerCardLayer';
import { useNewSlot } from '@/utils/slot';
import RecordBook, { RecordStrip } from '../stats/RecordBook';
import PositionLeaders from '../stats/PositionLeaders';
import StatTables from '../stats/StatTables';
import StatsStadium from '../stats/visual/StatsStadium';
import CrowdDivider from '../stats/visual/CrowdDivider';
import '../stats/visual/statsArena.css';
import { HEADLINE_IDS, LEADER_IDS, buildRecordBook, pickBoards } from '../stats/records';
import StatsHub from '../stats/hub/StatsHub';
import { ClockPage, GamePage, GraphsPage, HeadToHead, PlayerDeepDive, PlayersInsights, TeamRankingsTab, ViewLoading, prefetchStatsSub } from '../stats/hub/lazyViews';
import { buildHash, useHubRoute, type StatsSub } from '../stats/hub/hashRoute';
import { reducedMotion } from '@/utils/motion';
import { usePhone } from '@/hooks/usePhone';
import { cn } from '@/lib/utils';

/**
 * In-page jumps on the Players sub-tab (each is linkable: #stats/players/<id>), in the page's top-to-bottom order so
 * the phone chip row's highlight moves steadily left to right while scrolling.
 */
const JUMPS = [
  { id: 'record-book', label: 'Records' },
  { id: 'analytics', label: 'Advanced' },
  { id: 'landscape', label: 'Landscape' },
  { id: 'hidden-gems', label: 'Hidden Gems' },
  { id: 'league-shape', label: 'League Shape' },
  { id: 'efficiency', label: 'Efficiency' },
  { id: 'leaders', label: 'Leaders' },
  { id: 'tables', label: 'Full Tables' },
];

/** Phones: which jump section is in view (the last one whose top has passed under the sticky bars) */
const useSpy = (on: boolean) => {
  const [id, setId] = useState<string | null>(null);
  useEffect(() => {
    if (!on) return;
    let raf = 0;
    // Read once (and on resize), not every scroll frame: a style read per frame forces a recalc mid-scroll
    let line = 0;
    const measure = () => {
      line = (parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop) || 0) + 110;
    };
    measure();
    const check = () => {
      raf = 0;
      // The section whose top most recently passed the line (measured, so a layout change can't desync the chips)
      let cur: string | null = null;
      let best = -Infinity;
      for (const j of JUMPS) {
        const top = document.getElementById(j.id)?.getBoundingClientRect().top;
        if (top != null && top <= line && top > best) {
          best = top;
          cur = j.id;
        }
      }
      setId(cur);
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(check);
    };
    check();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', measure, { passive: true });
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', measure);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [on]);
  return id;
};

/**
 * Phones: the page's sections as a sticky, finger-scrolled chip row that follows the scroll. The scroll spy's state
 * lives here, so a new section in view re-renders only this row, never the whole Stats page behind it.
 */
const PhoneJumpChips = ({ current, onJump }: { current?: string; onJump: (id: string) => void }) => {
  const spied = useSpy(true);
  const jumpRow = useRef<HTMLDivElement | null>(null);
  // Keep the section in view centred in the chip row; above the first section (nothing in view) the row goes back to its start
  useEffect(() => {
    const row = jumpRow.current;
    if (!row) return;
    const behavior: ScrollBehavior = reducedMotion() ? 'auto' : 'smooth';
    if (!spied) {
      row.scrollTo({ left: 0, behavior });
      return;
    }
    const chip = row.querySelector<HTMLElement>(`[data-jump="${spied}"]`);
    if (chip) row.scrollTo({ left: Math.max(0, chip.offsetLeft - row.clientWidth / 2 + chip.offsetWidth / 2), behavior });
  }, [spied]);
  return (
    <nav aria-label="On this page" className="chrome-follow sticky z-30 -mx-4 !mt-4 border-b border-line/70 bg-night py-2" style={{ top: 'var(--site-header-h, 0px)' }}>
      <div ref={jumpRow} className="flex gap-1.5 overflow-x-auto px-4 scrollbar-none">
        {JUMPS.map((j) => (
          <a
            key={j.id}
            data-jump={j.id}
            href={buildHash({ tab: 'career', sub: 'players', section: j.id })}
            aria-current={spied === j.id ? 'location' : undefined}
            onClick={(e) => {
              e.preventDefault();
              onJump(j.id);
              if (current === j.id) document.getElementById(j.id)?.scrollIntoView({ block: 'start', behavior: reducedMotion() ? 'auto' : 'smooth' });
            }}
            // No colour transition: the highlight follows the scroll, and a colour fade per section change repainted the
            // page mid-scroll
            className={cn(
              'inline-flex h-10 shrink-0 items-center rounded-full border px-3.5 text-sm font-semibold',
              spied === j.id ? 'border-gold bg-gold text-night' : 'border-line bg-night/60 text-secondary-foreground',
            )}
          >
            {j.label}
          </a>
        ))}
      </div>
    </nav>
  );
};

/**
 * Stats hub. A sticky sub-nav switches between Players (record strip, records, efficiency, leaders, full tables, Analytics Lab),
 * Teams, Graphs (the Graph Builder), Head-to-Head and Deep Dive (one player, full width). The sub-tab lives in the
 * URL hash (see stats/hub/hashRoute.ts).
 */
const CareerTab = () => {
  const { careerData, isLoading, getAllPlayers } = useLeague();
  const { route, navigate } = useHubRoute();
  // The open player card lives in a slot: opening it re-renders the card only, not the whole hub behind it
  const cardSlot = useNewSlot<Player | null>(null);
  const setSelectedPlayer = cardSlot.set;
  const sub: StatsSub = route.sub ?? 'players';
  const phone = usePhone();
  const autoReveal = useAutoReveal<HTMLDivElement>();

  const book = useMemo(() => buildRecordBook(careerData, 10), [careerData]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const players = useMemo(() => getAllPlayers(), [getAllPlayers, careerData]);


  if (!careerData) {
    // The league loads from the bundled data file; this only shows for a moment (or if that file is missing).
    return <PixelLoader label="Stats" what="the league" minHeight="70vh" className="container justify-start pt-[18vh]" />;
  }

  if (isLoading) {
    return <PixelLoader label="Stats" what="league data" minHeight="70vh" className="container justify-start pt-[18vh]" />;
  }

  const headline = pickBoards(book.boards, HEADLINE_IDS);
  const leaders = pickBoards(book.boards, LEADER_IDS);

  return (
    <StatsHub
      sub={sub}
      section={route.section}
      onSubChange={(s) => navigate({ tab: 'career', sub: s })}
      players={players}
      onOpenPlayer={setSelectedPlayer}
      onPrefetch={prefetchStatsSub}
    >
      {/* Each sub-tab cross-fades in with a short rise (.rv-view-in). The switch is a transition (hashRoute), and the
          Suspense below stays mounted, so the old sub-tab stays up until a lazy one has loaded. */}
      {sub === 'players' && (
        <div ref={autoReveal} className="rv-view-in stats-arena container space-y-10 py-6 sm:py-8">
          {/* The opener: a night stadium (jumbotron counts, the record holders on the turf, the live chase) */}
          <StatsStadium data={careerData} book={book} headline={headline} onSelect={setSelectedPlayer} />
          <nav aria-label="On this page" className="-mt-6 flex flex-wrap justify-center gap-x-3 gap-y-1 text-sm max-sm:hidden">
            {JUMPS.map((j) => (
              <a
                key={j.id}
                href={buildHash({ tab: 'career', sub: 'players', section: j.id })}
                onClick={(e) => {
                  if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
                  e.preventDefault();
                  navigate({ tab: 'career', sub: 'players', section: j.id }, { replace: true });
                  // Same section clicked twice: the route doesn't change, so scroll directly.
                  if (route.section === j.id) document.getElementById(j.id)?.scrollIntoView({ block: 'start', behavior: reducedMotion() ? 'auto' : 'smooth' });
                }}
                className="link-chip text-muted-foreground hover:text-gold"
              >
                {j.label}
              </a>
            ))}
          </nav>

          {/* Phones: the page's sections as a sticky, finger-scrolled chip row that follows the scroll */}
          {phone && (
            <PhoneJumpChips
              current={route.section}
              onJump={(id) => navigate({ tab: 'career', sub: 'players', section: id }, { replace: true })}
            />
          )}

          {headline.length > 0 && (
            <Reveal>
              <div className="mo-rise">
                <RecordStrip headline={headline} players={players} onSelect={setSelectedPlayer} />
              </div>
            </Reveal>
          )}

          <CrowdDivider />

          {/* Analytics Lab, Landscape, Hidden Gems, League Shape: their own chunk (stats/hub/lazyViews) */}
          <Suspense fallback={<ViewLoading label="advanced stats" tall={false} />}>
            <PlayersInsights data={careerData} onSelect={setSelectedPlayer} />
          </Suspense>

          <CrowdDivider />

          <Reveal>
            <div className="mo-rise">
              <DeferredSection ids={['efficiency']} minHeight={900}>
                <RecordBook leaders={leaders} pace={book.pace} onSelect={setSelectedPlayer} />
              </DeferredSection>
            </div>
          </Reveal>

          <Reveal>
            <div className="mo-rise">
              <DeferredSection ids={['leaders']} minHeight={700}>
                <PositionLeaders boards={book.boards} data={careerData} onSelect={setSelectedPlayer} />
              </DeferredSection>
            </div>
          </Reveal>

          <CrowdDivider />

          <Reveal>
            <div className="mo-rise">
              <DeferredSection ids={['tables']} minHeight={900}>
                <StatTables data={careerData} />
              </DeferredSection>
            </div>
          </Reveal>
        </div>
      )}

      <Suspense fallback={<ViewLoading label={sub} />}>
      <div key={sub} className={sub === 'players' ? undefined : 'rv-view-in'}>
      {sub === 'teams' && <TeamRankingsTab />}
      {sub === 'game' && <GamePage gameId={route.q?.id} />}

      {/* Graph Builder full page (src/components/stats/graph); the URL's gx / gy / pos… are the chart. */}
      {sub === 'graphs' && <GraphsPage data={careerData} onSelect={setSelectedPlayer} />}

      {sub === 'h2h' && (
        <div className="container py-6 sm:py-8">
          <HeadToHead data={careerData} onSelect={setSelectedPlayer} />
        </div>
      )}

      {/* Deep Dive (src/components/stats/comps): one player, full width. The hash's ?p= is the player (none = empty state). */}
      {sub === 'deepdive' && (
        <div className="container py-6 sm:py-8">
          <PlayerDeepDive
            data={careerData}
            onSelect={setSelectedPlayer}
            initialPlayerKey={route.p}
            onPlayerChange={(key) => navigate({ tab: 'career', sub: 'deepdive', p: key }, { replace: true })}
          />
        </div>
      )}

      {/* The Clock (src/components/clock): ages from the live save; the view is the hash's section */}
      {sub === 'clock' && <ClockPage players={players} onSelect={setSelectedPlayer} />}
      </div>
      </Suspense>

      <PlayerCardLayer slot={cardSlot} />
    </StatsHub>
  );
};

export default CareerTab;
